# A simple heuristic for deciding whether to fine-tune
def should_fine_tune(volume_per_day, task_stable, has_quality_data, facts_change_often):
    if facts_change_often:
        return "Use RAG instead"
    if not task_stable:
        return "Keep iterating with prompting first"
    if not has_quality_data:
        return "Collect data before considering fine-tuning"
    if volume_per_day < 100:
        return "Likely not worth it yet, keep prompting"
    return "Fine-tuning is worth evaluating"
